(978227, 115055, 20779, '<td valign="top">I am afraid I am not getting it; I don''t see the connection to poverty.  I believe you will also get scored low for the image size and it appearing to be a snapshot of a statue.</td>', 'I am afraid I am not getting it; I don''t see the connection to poverty.  I believe you will also get scored low for the image size and it appearing to be a snapshot of a statue.', '2004-10-28 20:42:38.000000', NULL, 1),
(978238, 115172, 21621, '<td valign="top">Great shot, nice work.</td>', 'Great shot, nice work.', '2004-10-28 20:49:00.000000', NULL, 1),
(978251, 114804, 21621, '<td valign="top">Great capture, excellent choice for the challenge, nice work.</td>', 'Great capture, excellent choice for the challenge, nice work.', '2004-10-28 20:55:52.000000', NULL, 1),
