(978254, 115828, 20779, '<td valign="top">Your image may be voted low due to some people having an issue with the concept, but for me, it appears to be a snapshot in somewhat poor focus to score highly.</td>', 'Your image may be voted low due to some people having an issue with the concept, but for me, it appears to be a snapshot in somewhat poor focus to score highly.', '2004-10-28 21:01:13.000000', NULL, 1),
(978258, 115620, 20779, '<td valign="top">I think I am missing something here - I honestly don''t get the poverty connection. I also think you will most likely suffer a low score due to it appearing to be a snapshot of a statue.</td>', 'I think I am missing something here - I honestly don''t get the poverty connection. I also think you will most likely suffer a low score due to it appearing to be a snapshot of a statue.', '2004-10-28 21:03:04.000000', NULL, 1),
(978260, 115468, 20779, '<td valign="top">I am sorry, but I am not getting the connection to poverty. The focus and lighting also appear to be a bit off. Just an opinion.</td>', 'I am sorry, but I am not getting the connection to poverty. The focus and lighting also appear to be a bit off. Just an opinion.', '2004-10-28 21:07:12.000000', NULL, 1),
(978262, 114884, 20779, '<td valign="top">The image is too dark and blurry on my monitor to really "get", I regret.</td>', 'The image is too dark and blurry on my monitor to really "get", I regret.', '2004-10-28 21:10:12.000000', NULL, 1),
(978263, 115469, 20779, '<td valign="top">The stretch for this one is too far in my opinion, and the composition not very interesting - but only one opinion obviously.</td>', 'The stretch for this one is too far in my opinion, and the composition not very interesting - but only one opinion obviously.', '2004-10-28 21:11:21.000000', NULL, 1),
(978264, 115764, 28643, '<td valign="top">This photo is perfect in the black and white format in my opinion...it has you concentrate more on the weathering of the wood, the opened grain from exposure to water and sun while also giving you that bleak or unemotional view on a very emotional circumstance.   The vines distracted me some from the window and slats of the home...but was still captivating.</td>', 'This photo is perfect in the black and white format in my opinion...it has you concentrate more on the weathering of the wood, the opened grain from exposure to water and sun while also giving you that bleak or unemotional view on a very emotional circumstance.   The vines distracted me some from the window and slats of the home...but was still captivating.', '2004-10-28 21:11:41.000000', NULL, 1),
(978266, 114656, 20779, '<td valign="top">Interesting concept, but too blurry and ill-composed for me, and I would consider real poverty as "not" a choice.</td>', 'Interesting concept, but too blurry and ill-composed for me, and I would consider real poverty as "not" a choice.', '2004-10-28 21:12:27.000000', NULL, 1),
(978267, 115194, 28643, '<td valign="top">This made me smile and laugh out loud...as I was just today contemplating the draw between a Canon 20D or lesser model...insert my head in that picture as well. LOL</td>', 'This made me smile and laugh out loud...as I was just today contemplating the draw between a Canon 20D or lesser model...insert my head in that picture as well. LOL', '2004-10-28 21:12:42.000000', NULL, 1),
(978268, 115151, 20779, '<td valign="top">Interesting concept, but I feel that indebtedness is far removed from poverty - it is a choice, although a bad one.</td>', 'Interesting concept, but I feel that indebtedness is far removed from poverty - it is a choice, although a bad one.', '2004-10-28 21:13:41.000000', NULL, 1),
