(980673, 115391, 28742, '<td valign="top">Great shot. I would change the title to something about a cage though.</td>', 'Great shot. I would change the title to something about a cage though.', '2004-10-30 20:38:42.000000', NULL, 1),
(980675, 115077, 11653, '<td valign="top">Very powerful image!</td>', 'Very powerful image!', '2004-10-30 20:39:42.000000', NULL, 1),
(980676, 115557, 6179, '<td valign="top">Very shallow DOF. Could have used more.</td>', 'Very shallow DOF. Could have used more.', '2004-10-30 20:40:13.000000', NULL, 1),
(980677, 115739, 11653, '<td valign="top">Great lighting.</td>', 'Great lighting.', '2004-10-30 20:40:53.000000', NULL, 1),
(980678, 115764, 11653, '<td valign="top">Love the lines in this</td>', 'Love the lines in this', '2004-10-30 20:41:59.000000', NULL, 1),
(980680, 115426, 11653, '<td valign="top">Nice lines, textures and lighting.</td>', 'Nice lines, textures and lighting.', '2004-10-30 20:43:05.000000', NULL, 1),
(980681, 115401, 28742, '<td valign="top">What? I know this guy. He''s one of Sony''s executives. Every weekend he takes a basket of Sushi to the park to feed the pigeons.  :-)  Good shot.</td>', 'What? I know this guy. He''s one of Sony''s executives. Every weekend he takes a basket of Sushi to the park to feed the pigeons.  :-)  Good shot.', '2004-10-30 20:43:10.000000', NULL, 1),
(980682, 115781, 28742, '<td valign="top">Ok, the place is a dump - but how ''bout that view?!  :-) <br/>Great shot!</td>', 'Ok, the place is a dump - but how ''bout that view?!  :-) Great shot!', '2004-10-30 20:44:09.000000', NULL, 1),
(980684, 114766, 28742, '<td valign="top">The tilt just doesn''t do it for me, but everything else is good.</td>', 'The tilt just doesn''t do it for me, but everything else is good.', '2004-10-30 20:48:03.000000', NULL, 1),
(980687, 115422, 25218, '<td valign="top">This is so good, I just wish it were a bit sharper - so I''ll give it a 9, instead of a 10.</td>', 'This is so good, I just wish it were a bit sharper - so I''ll give it a 9, instead of a 10.', '2004-10-30 21:00:27.000000', NULL, 1),
(980692, 115557, 25218, '<td valign="top">I would have gone with a title relating to the stock market crash instead, because I associate the ''30s more with the Depression... in any case, the extreme narrow depth of field is distracting. I would have liked to have seen the whole penny in focus. Great idea, though, and the background choice complements the copper well. 7</td>', 'I would have gone with a title relating to the stock market crash instead, because I associate the ''30s more with the Depression... in any case, the extreme narrow depth of field is distracting. I would have liked to have seen the whole penny in focus. Great idea, though, and the background choice complements the copper well. 7', '2004-10-30 21:04:39.000000', NULL, 1),
(980693, 115425, 16618, '<td valign="top">The only thing that could have given this more impact is if there were catchlights in his eyes.  This is a very powerful shot, his expression is so emotional.  Great job!</td>', 'The only thing that could have given this more impact is if there were catchlights in his eyes.  This is a very powerful shot, his expression is so emotional.  Great job!', '2004-10-30 21:05:34.000000', NULL, 1),
(980694, 115258, 25218, '<td valign="top">very original idea, but I''m not sure what (s)he is being tempted by?</td>', 'very original idea, but I''m not sure what (s)he is being tempted by?', '2004-10-30 21:06:54.000000', NULL, 1),
(980695, 115781, 16618, '<td valign="top">Very interesting shot.  The texture of the walls/ceiling against the sky (and beautiful colors of the sunset) make this a very eye-catching shot.  Great job!</td>', 'Very interesting shot.  The texture of the walls/ceiling against the sky (and beautiful colors of the sunset) make this a very eye-catching shot.  Great job!', '2004-10-30 21:07:04.000000', NULL, 1),
(980697, 114351, 16618, '<td valign="top">I wish that you were able to get more light in his eyes (but I understand that it is hard to do that when taking a candid).  He has so much emotion in his face, and I wish it wasn''t cropped off, it would''ve impacted me more, personally, to see more of his face.  Great choice of subject!</td>', 'I wish that you were able to get more light in his eyes (but I understand that it is hard to do that when taking a candid).  He has so much emotion in his face, and I wish it wasn''t cropped off, it would''ve impacted me more, personally, to see more of his face.  Great choice of subject!', '2004-10-30 21:09:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(980698, 115767, 25218, '<td valign="top">I love the lines and the way you framed this. My nit pick would be that without the title, I wouldn''t have known it''s a house.</td>', 'I love the lines and the way you framed this. My nit pick would be that without the title, I wouldn''t have known it''s a house.', '2004-10-30 21:09:15.000000', NULL, 1),
(980699, 114454, 16618, '<td valign="top">The longer you look at this photo, the more details you find...I love the guy sleeping?, and the little dog.  Great shot!</td>', 'The longer you look at this photo, the more details you find...I love the guy sleeping?, and the little dog.  Great shot!', '2004-10-30 21:09:58.000000', NULL, 1),
(980700, 115522, 16618, '<td valign="top">I just wish the picture was bigger and more cropped in on the subject so you could see the details of their face.</td>', 'I just wish the picture was bigger and more cropped in on the subject so you could see the details of their face.', '2004-10-30 21:10:58.000000', NULL, 1),
(980701, 115018, 16618, '<td valign="top">Great concept and lighting!</td>', 'Great concept and lighting!', '2004-10-30 21:11:25.000000', NULL, 1),
(980703, 115493, 16618, '<td valign="top">Great concept!  The colors are very eye-catching!</td>', 'Great concept!  The colors are very eye-catching!', '2004-10-30 21:12:03.000000', NULL, 1),
(980705, 115719, 16618, '<td valign="top">The texture is amazing!  Great shot!</td>', 'The texture is amazing!  Great shot!', '2004-10-30 21:12:43.000000', NULL, 1),
(980706, 114892, 25218, '<td valign="top">I actually like the post processing you''ve done. good job!</td>', 'I actually like the post processing you''ve done. good job!', '2004-10-30 21:12:48.000000', NULL, 1),
(980707, 115364, 16618, '<td valign="top">I wish the focus was sharper to see more details in their face.  It is an interesting shot to see so many people in the background just going about their day not noticing the pair...very sad.</td>', 'I wish the focus was sharper to see more details in their face.  It is an interesting shot to see so many people in the background just going about their day not noticing the pair...very sad.', '2004-10-30 21:14:26.000000', NULL, 1),
(980709, 115622, 16618, '<td valign="top">Great shot!  I love the simplicity of it and choice of B&amp;W!</td>', 'Great shot!  I love the simplicity of it and choice of B&W!', '2004-10-30 21:15:01.000000', NULL, 1),
(980710, 114804, 16618, '<td valign="top">Great capture!  I love the choice of B&amp;W and the expression on their faces!</td>', 'Great capture!  I love the choice of B&W and the expression on their faces!', '2004-10-30 21:16:21.000000', NULL, 1),
(980712, 115679, 16618, '<td valign="top">There''s too much of the parking lot in this shot to make it very interesting.  You can''t really tell what you''re looking at.</td>', 'There''s too much of the parking lot in this shot to make it very interesting.  You can''t really tell what you''re looking at.', '2004-10-30 21:17:07.000000', NULL, 1),
(980713, 115674, 16618, '<td valign="top">I wish that the picture was larger to see the detail.</td>', 'I wish that the picture was larger to see the detail.', '2004-10-30 21:17:33.000000', NULL, 1),
(980715, 115612, 16618, '<td valign="top">Great emotional shot!</td>', 'Great emotional shot!', '2004-10-30 21:18:38.000000', NULL, 1),
(980716, 115401, 16618, '<td valign="top">I wish we could see more of his face, I think it would have had more impact.</td>', 'I wish we could see more of his face, I think it would have had more impact.', '2004-10-30 21:19:29.000000', NULL, 1),
(980718, 115834, 23471, '<td valign="top">well done. i have seen this same idea a lot throughout the competition but i must say, you have done an excellent job of it.  good luck</td>', 'well done. i have seen this same idea a lot throughout the competition but i must say, you have done an excellent job of it.  good luck', '2004-10-30 21:20:48.000000', NULL, 1),
