(981405, 115419, 28775, '<td valign="top">The glass looks "mostly full" ... nice variation in tone.</td>', 'The glass looks "mostly full" ... nice variation in tone.', '2004-10-31 14:49:06.000000', NULL, 1),
(981406, 115350, 26679, '<td valign="top">This is a well focused photograph of a building. From your title I would guess its a school, but that is a guess. A photograph should give me a little steer<br/> <br/>Here I really struggle on the poverty theme, and the tiltle would seem to miss the theme as well.<br/></td>', 'This is a well focused photograph of a building. From your title I would guess its a school, but that is a guess. A photograph should give me a little steer Here I really struggle on the poverty theme, and the tiltle would seem to miss the theme as well.', '2004-10-31 14:49:31.000000', NULL, 1),
(981407, 115390, 28775, '<td valign="top">Is that a skull in the window? I don''t see the connection between nuclear war and this photo. Or poverty and this photo.</td>', 'Is that a skull in the window? I don''t see the connection between nuclear war and this photo. Or poverty and this photo.', '2004-10-31 14:50:16.000000', NULL, 1),
(981408, 114765, 28775, '<td valign="top">Now YOU understand poverty!!! Great grasp of the concept!</td>', 'Now YOU understand poverty!!! Great grasp of the concept!', '2004-10-31 14:50:54.000000', NULL, 1),
(981409, 114567, 28775, '<td valign="top">Since you quote scripture, we may carry nothing out - but if we''re going to heaven, who needs the rags we earn on earth. Nice composition.</td>', 'Since you quote scripture, we may carry nothing out - but if we''re going to heaven, who needs the rags we earn on earth. Nice composition.', '2004-10-31 14:51:44.000000', NULL, 1),
(981410, 114951, 28775, '<td valign="top">Like the rainbow prosmise imagery.</td>', 'Like the rainbow prosmise imagery.', '2004-10-31 14:52:14.000000', NULL, 1),
(981415, 115803, 28775, '<td valign="top">Didn''t Dolly Parton live here once? Nice picture. I like the contrast of the tub and the barnwood.</td>', 'Didn''t Dolly Parton live here once? Nice picture. I like the contrast of the tub and the barnwood.', '2004-10-31 14:53:15.000000', NULL, 1),
(981417, 115771, 28775, '<td valign="top">For all the van dwellers out there I assume. Never could keep plants alive when I was living in my car. Like the use of plants and a car - contrast.</td>', 'For all the van dwellers out there I assume. Never could keep plants alive when I was living in my car. Like the use of plants and a car - contrast.', '2004-10-31 14:54:41.000000', NULL, 1),
(981418, 114782, 26679, '<td valign="top">A WORLD UPSIDE DOWN,...Interesting perspective, Interesting question, but it does not evoke poverty for me. Itdoes however chalenge my perceptions, and for that I thank you.</td>', 'A WORLD UPSIDE DOWN,...Interesting perspective, Interesting question, but it does not evoke poverty for me. Itdoes however chalenge my perceptions, and for that I thank you.', '2004-10-31 14:54:47.000000', NULL, 1),
(981419, 115834, 28775, '<td valign="top">Been there done that - grew a couple of fins...nice touch with the shadows etc.</td>', 'Been there done that - grew a couple of fins...nice touch with the shadows etc.', '2004-10-31 14:55:22.000000', NULL, 1),
(981420, 115818, 28775, '<td valign="top">Ah! The impoverished soul! I love it! Nice grasp of the concept, weaving of reality - ie. philosophy in front of the church - contrast between soul, intellect, God and sustenance. Very well thought out and excellent commentary on all aspects of any poverty debate - spiritual, financial, intellectual or positional!</td>', 'Ah! The impoverished soul! I love it! Nice grasp of the concept, weaving of reality - ie. philosophy in front of the church - contrast between soul, intellect, God and sustenance. Very well thought out and excellent commentary on all aspects of any poverty debate - spiritual, financial, intellectual or positional!', '2004-10-31 14:57:17.000000', NULL, 1),
(981422, 115796, 26679, '<td valign="top">Not sure a photo of a deck evokes poverty for me. However as a photograph you have got a good compositional balance, and some sharp focusing</td>', 'Not sure a photo of a deck evokes poverty for me. However as a photograph you have got a good compositional balance, and some sharp focusing', '2004-10-31 14:57:33.000000', NULL, 1),
(981423, 115497, 28775, '<td valign="top">Poor taste - unless you''re Elton John or Liberace. Love the use of color!</td>', 'Poor taste - unless you''re Elton John or Liberace. Love the use of color!', '2004-10-31 14:57:49.000000', NULL, 1),
(981425, 115468, 28775, '<td valign="top">Nice photo. Doesn''t unaddress the poverty issue without the caption...but enjoy the "jewels" of water in the web.</td>', 'Nice photo. Doesn''t unaddress the poverty issue without the caption...but enjoy the "jewels" of water in the web.', '2004-10-31 14:58:44.000000', NULL, 1),
(981426, 115720, 28775, '<td valign="top">Would be nice to have had a verse highlighted or readable...but to know God is to have all riches.</td>', 'Would be nice to have had a verse highlighted or readable...but to know God is to have all riches.', '2004-10-31 14:59:34.000000', NULL, 1),
(981430, 115859, 28775, '<td valign="top">Great photo! And heck of a thing to do - to kill the pig in search of the bacon.</td>', 'Great photo! And heck of a thing to do - to kill the pig in search of the bacon.', '2004-10-31 15:00:13.000000', NULL, 1),
(981431, 114834, 28775, '<td valign="top">Depressing as hell. Sure captures the theme well! Love the color.</td>', 'Depressing as hell. Sure captures the theme well! Love the color.', '2004-10-31 15:00:48.000000', NULL, 1),
(981433, 115717, 28775, '<td valign="top">I had a slumlord and an apartment like this once. Nice blend of texture.</td>', 'I had a slumlord and an apartment like this once. Nice blend of texture.', '2004-10-31 15:01:32.000000', NULL, 1),
(981435, 115415, 28775, '<td valign="top">Tattered chair yes - poverty? With all those paintings and color?</td>', 'Tattered chair yes - poverty? With all those paintings and color?', '2004-10-31 15:02:34.000000', NULL, 1),
(981436, 115557, 26679, '<td valign="top">This image is quite evocotive, and I realy like it, howver you do have to bare in mind that there will be a significant number who are like myself are non Americans and will not have the same assiciation with 1929 Wall Street Crash.<br/> <br/>The UK depression was  more focuseed in the mid 1930s.</td>', 'This image is quite evocotive, and I realy like it, howver you do have to bare in mind that there will be a significant number who are like myself are non Americans and will not have the same assiciation with 1929 Wall Street Crash. The UK depression was  more focuseed in the mid 1930s.', '2004-10-31 15:03:01.000000', NULL, 1),
(981437, 115175, 28775, '<td valign="top">Poor but happy.</td>', 'Poor but happy.', '2004-10-31 15:03:04.000000', NULL, 1),
(981438, 115522, 28775, '<td valign="top">makes me cold and depressed to just see this guy. Good illustration of poverty.</td>', 'makes me cold and depressed to just see this guy. Good illustration of poverty.', '2004-10-31 15:03:42.000000', NULL, 1),
(981439, 115151, 28775, '<td valign="top">Nice play on words and good illustration of theme!</td>', 'Nice play on words and good illustration of theme!', '2004-10-31 15:04:07.000000', NULL, 1),
(981440, 114861, 28775, '<td valign="top">Doesn''t look like the blue is helping keep too many bad spirits out! Love the color, the atmosphere. Nice picture!</td>', 'Doesn''t look like the blue is helping keep too many bad spirits out! Love the color, the atmosphere. Nice picture!', '2004-10-31 15:04:50.000000', NULL, 1),
(981441, 114328, 28775, '<td valign="top">Nice portrait....</td>', 'Nice portrait....', '2004-10-31 15:05:16.000000', NULL, 1),
(981444, 115765, 28775, '<td valign="top">But not sleeping there....</td>', 'But not sleeping there....', '2004-10-31 15:06:30.000000', NULL, 1),
(981446, 114537, 28775, '<td valign="top">Probably searching for a half-eaten sandwich and old aluminum cans. Nice portrayal of poverty.</td>', 'Probably searching for a half-eaten sandwich and old aluminum cans. Nice portrayal of poverty.', '2004-10-31 15:07:21.000000', NULL, 1),
(981447, 115796, 28775, '<td valign="top">and the poverty is???</td>', 'and the poverty is???', '2004-10-31 15:08:09.000000', NULL, 1),
(981448, 115609, 28775, '<td valign="top">looks like a nice neighborhood to me!</td>', 'looks like a nice neighborhood to me!', '2004-10-31 15:08:34.000000', NULL, 1),
(981450, 115472, 28775, '<td valign="top">Like the color and angle.</td>', 'Like the color and angle.', '2004-10-31 15:09:08.000000', NULL, 1),
(981451, 115623, 28775, '<td valign="top">This guy''s out here a lot...I can tell by the magazines under his butt. Very good image of poverty.</td>', 'This guy''s out here a lot...I can tell by the magazines under his butt. Very good image of poverty.', '2004-10-31 15:10:02.000000', NULL, 1),
(981452, 115674, 28775, '<td valign="top">Living in this would certainly be both poverty and a dream for those so poor.</td>', 'Living in this would certainly be both poverty and a dream for those so poor.', '2004-10-31 15:10:34.000000', NULL, 1),
(981455, 115445, 28775, '<td valign="top">This kid knows poverty. There''s dirt, then there''s the accumulated dirt of poverty. This kid hasn''t bathed in a while....eating junk food....good portrait of the face of poverty.</td>', 'This kid knows poverty. There''s dirt, then there''s the accumulated dirt of poverty. This kid hasn''t bathed in a while....eating junk food....good portrait of the face of poverty.', '2004-10-31 15:11:32.000000', NULL, 1),
(981457, 115739, 28775, '<td valign="top">Nice imagery, tones. Like the "looking up" towards the light/hope.</td>', 'Nice imagery, tones. Like the "looking up" towards the light/hope.', '2004-10-31 15:12:22.000000', NULL, 1),
(981459, 114544, 28775, '<td valign="top">Would like to have seen more of the cup, or the cup and hand unfocused and a tighter shot on the person in the background.</td>', 'Would like to have seen more of the cup, or the cup and hand unfocused and a tighter shot on the person in the background.', '2004-10-31 15:13:11.000000', NULL, 1),
(981460, 115793, 28775, '<td valign="top">Ah, the poverty of the rural south....and the trailer is SO symbolic of the poverty of the transient. Nice colors...blue sky, red building....</td>', 'Ah, the poverty of the rural south....and the trailer is SO symbolic of the poverty of the transient. Nice colors...blue sky, red building....', '2004-10-31 15:14:35.000000', NULL, 1),
(981461, 115477, 28775, '<td valign="top">would like to have seen this in color.</td>', 'would like to have seen this in color.', '2004-10-31 15:15:04.000000', NULL, 1),
(981462, 115603, 28775, '<td valign="top">Must be student or starving artist type poverty! Laughed out loud - been there, eaten that! Definitely impoverished when I did! Can no longer eat Ramen...</td>', 'Must be student or starving artist type poverty! Laughed out loud - been there, eaten that! Definitely impoverished when I did! Can no longer eat Ramen...', '2004-10-31 15:16:02.000000', NULL, 1),
(981464, 115781, 28775, '<td valign="top">Good color in the sky, would loved to have seen a close-up of the face or tighter shot of the entire scene. Mental poverty as a theme would be more vivid if you had a tortured, depressed, anguished or even blank face. Still, nice layout, composition etc.</td>', 'Good color in the sky, would loved to have seen a close-up of the face or tighter shot of the entire scene. Mental poverty as a theme would be more vivid if you had a tortured, depressed, anguished or even blank face. Still, nice layout, composition etc.', '2004-10-31 15:17:37.000000', NULL, 1),
(981465, 115768, 28775, '<td valign="top">Fantastic title! And you got the poverty theme down perfectly.</td>', 'Fantastic title! And you got the poverty theme down perfectly.', '2004-10-31 15:18:14.000000', NULL, 1),
(981468, 114892, 28775, '<td valign="top">Definitely depressing place to live. Lots of poverty here. Photo is a little dark.</td>', 'Definitely depressing place to live. Lots of poverty here. Photo is a little dark.', '2004-10-31 15:19:02.000000', NULL, 1),
(981469, 115612, 28775, '<td valign="top">Like this photo and the idea of a soul impoverished. Nice.</td>', 'Like this photo and the idea of a soul impoverished. Nice.', '2004-10-31 15:19:37.000000', NULL, 1),
(981470, 114454, 28775, '<td valign="top">Poor, but poverty? Would like a close-up of one or more of the faces.</td>', 'Poor, but poverty? Would like a close-up of one or more of the faces.', '2004-10-31 15:20:30.000000', NULL, 1),
(981471, 115598, 28775, '<td valign="top">????</td>', '????', '2004-10-31 15:20:47.000000', NULL, 1),
(981472, 115682, 28775, '<td valign="top">Cute. Love the pig too.</td>', 'Cute. Love the pig too.', '2004-10-31 15:21:10.000000', NULL, 1),
(981473, 115669, 28775, '<td valign="top">Nice illustration. Good grasp of the concept.</td>', 'Nice illustration. Good grasp of the concept.', '2004-10-31 15:21:43.000000', NULL, 1),
(981474, 115252, 28775, '<td valign="top">needs human element I think.</td>', 'needs human element I think.', '2004-10-31 15:22:09.000000', NULL, 1),
(981476, 114678, 28775, '<td valign="top">Like the use of the cat. A few more cans would have emphasized the empty cupboard. Nice overall.</td>', 'Like the use of the cat. A few more cans would have emphasized the empty cupboard. Nice overall.', '2004-10-31 15:22:52.000000', NULL, 1),
