(981479, 115621, 28775, '<td valign="top">Needs more contrast, more focus on one particular element in the photo - lots of potential there - what with the church in the background...maybe a shot from the road ....more detail would work well in this.</td>', 'Needs more contrast, more focus on one particular element in the photo - lots of potential there - what with the church in the background...maybe a shot from the road ....more detail would work well in this.', '2004-10-31 15:24:41.000000', NULL, 1),
(981482, 115453, 28775, '<td valign="top">Like the use of color to get the "coldness" across. Looks like a miserable place to visit.</td>', 'Like the use of color to get the "coldness" across. Looks like a miserable place to visit.', '2004-10-31 15:25:38.000000', NULL, 1),
(981483, 115184, 28775, '<td valign="top">and the poverty is?</td>', 'and the poverty is?', '2004-10-31 15:26:04.000000', NULL, 1),
(981484, 115172, 28775, '<td valign="top">Nicely done. Captures how people will ignore people to pursue money/jewelry etc. good choice to use the sepia too.</td>', 'Nicely done. Captures how people will ignore people to pursue money/jewelry etc. good choice to use the sepia too.', '2004-10-31 15:27:03.000000', NULL, 1),
