(981490, 115056, 28775, '<td valign="top">Nice portrait of the child. Did you consider a tighter face shot ? the foreground is a little distracting with so  much going on in the background. The child is almost lost.</td>', 'Nice portrait of the child. Did you consider a tighter face shot ? the foreground is a little distracting with so  much going on in the background. The child is almost lost.', '2004-10-31 15:29:10.000000', NULL, 1),
(981492, 115799, 28775, '<td valign="top">almost fades away. Would like more contrast and definition. The black gaping door helps - but more of that would help.</td>', 'almost fades away. Would like more contrast and definition. The black gaping door helps - but more of that would help.', '2004-10-31 15:30:15.000000', NULL, 1),
(981494, 115449, 28775, '<td valign="top">Simple. Elegant.</td>', 'Simple. Elegant.', '2004-10-31 15:30:37.000000', NULL, 1),
(981497, 114766, 28775, '<td valign="top">Really nice use of line and contrast of color and texture.</td>', 'Really nice use of line and contrast of color and texture.', '2004-10-31 15:31:17.000000', NULL, 1),
(981498, 115822, 28775, '<td valign="top">simple. clean. nice texture.</td>', 'simple. clean. nice texture.', '2004-10-31 15:31:43.000000', NULL, 1),
(981499, 115606, 28775, '<td valign="top">All I would like to see is the person who lives here either coming or going or looking out the side. Nice photo!</td>', 'All I would like to see is the person who lives here either coming or going or looking out the side. Nice photo!', '2004-10-31 15:32:24.000000', NULL, 1),
(981500, 114957, 28775, '<td valign="top">LOL!!! How true....nice take on the challenge theme!</td>', 'LOL!!! How true....nice take on the challenge theme!', '2004-10-31 15:33:01.000000', NULL, 1),
(981502, 115098, 28775, '<td valign="top">Like the close-up of the hole. Would like to know/see who is doing the darning..</td>', 'Like the close-up of the hole. Would like to know/see who is doing the darning..', '2004-10-31 15:33:35.000000', NULL, 1),
(981503, 115402, 28775, '<td valign="top">He is poor if he has no beer! Nicely done.</td>', 'He is poor if he has no beer! Nicely done.', '2004-10-31 15:34:11.000000', NULL, 1),
(981504, 115391, 28775, '<td valign="top">true poverty.</td>', 'true poverty.', '2004-10-31 15:34:35.000000', NULL, 1),
(981505, 115594, 28775, '<td valign="top">Great color! Would loved to have seen the child''s face looking back at the camera.</td>', 'Great color! Would loved to have seen the child''s face looking back at the camera.', '2004-10-31 15:35:20.000000', NULL, 1),
(981507, 114936, 28775, '<td valign="top">Great shot! What a great "package" this would be with a few close-ups, the men eating...nicely done. Like the way you used color.</td>', 'Great shot! What a great "package" this would be with a few close-ups, the men eating...nicely done. Like the way you used color.', '2004-10-31 15:36:08.000000', NULL, 1),
(981508, 115523, 28775, '<td valign="top">Like the dark element - use of night to shoot the photo.</td>', 'Like the dark element - use of night to shoot the photo.', '2004-10-31 15:36:46.000000', NULL, 1),
(981511, 115695, 28775, '<td valign="top">Like the way the design moves the eye along. GOOD lines, direction, use of shadow and light.</td>', 'Like the way the design moves the eye along. GOOD lines, direction, use of shadow and light.', '2004-10-31 15:37:23.000000', NULL, 1),
(981514, 115426, 28775, '<td valign="top">Would be really strong with more focus on one element of the house. Almost too much going on.  Pulling back or zooming in....both would work.</td>', 'Would be really strong with more focus on one element of the house. Almost too much going on.  Pulling back or zooming in....both would work.', '2004-10-31 15:41:46.000000', NULL, 1),
(981515, 115469, 28775, '<td valign="top">Nice lines - color.</td>', 'Nice lines - color.', '2004-10-31 15:42:11.000000', NULL, 1),
