INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(981522, 114829, 28775, '<td valign="top">This kind of poverty I could handle!</td>', 'This kind of poverty I could handle!', '2004-10-31 15:45:45.000000', NULL, 1),
(981523, 115789, 28775, '<td valign="top">The title says it all.</td>', 'The title says it all.', '2004-10-31 15:46:09.000000', NULL, 1),
(981525, 115494, 28775, '<td valign="top">too close-up to get the impact of the glass.</td>', 'too close-up to get the impact of the glass.', '2004-10-31 15:46:44.000000', NULL, 1),
(981527, 115622, 28775, '<td valign="top">Like the motion, use of people and work in this photo. Would have loved to have seen a tighter shot of the child''s face.</td>', 'Like the motion, use of people and work in this photo. Would have loved to have seen a tighter shot of the child''s face.', '2004-10-31 15:47:49.000000', NULL, 1),
(981528, 115380, 28775, '<td valign="top">Loved this! Good color, humor and title.</td>', 'Loved this! Good color, humor and title.', '2004-10-31 15:48:17.000000', NULL, 1),
(981529, 115418, 28775, '<td valign="top">Funny and sadly, too true. Nice surprise photo.</td>', 'Funny and sadly, too true. Nice surprise photo.', '2004-10-31 15:48:55.000000', NULL, 1),
(981530, 115442, 28775, '<td valign="top">Would like to have seen more focus - blur of spoon and close-up almost too close-up.</td>', 'Would like to have seen more focus - blur of spoon and close-up almost too close-up.', '2004-10-31 15:49:40.000000', NULL, 1),
(981532, 115492, 28775, '<td valign="top">Like what you''re going for here. A close-up of the flamingo would have really given it punch. Could you get to a porch and do a long shot with the flamingo in focus? A telephoto maybe? Funny photo! Would like to see who lives there.</td>', 'Like what you''re going for here. A close-up of the flamingo would have really given it punch. Could you get to a porch and do a long shot with the flamingo in focus? A telephoto maybe? Funny photo! Would like to see who lives there.', '2004-10-31 15:51:04.000000', NULL, 1),
(981533, 115740, 28775, '<td valign="top">Close up of the man from chest high up would have been nice, but would have left the cup out. Still, nice photo.</td>', 'Close up of the man from chest high up would have been nice, but would have left the cup out. Still, nice photo.', '2004-10-31 15:51:56.000000', NULL, 1),
(981534, 115205, 28775, '<td valign="top">Nice illustration. Some dirt on the cheeks would have made her more of a "little match girl"</td>', 'Nice illustration. Some dirt on the cheeks would have made her more of a "little match girl"', '2004-10-31 15:52:44.000000', NULL, 1),
(981535, 115719, 28775, '<td valign="top">depressing, but nice textures in here.</td>', 'depressing, but nice textures in here.', '2004-10-31 15:53:12.000000', NULL, 1),
(981536, 115493, 28775, '<td valign="top">Would make a nice article illustration. Like the use of color.</td>', 'Would make a nice article illustration. Like the use of color.', '2004-10-31 15:53:48.000000', NULL, 1),
(981537, 115692, 28775, '<td valign="top">Like the bottle and the angles</td>', 'Like the bottle and the angles', '2004-10-31 15:54:16.000000', NULL, 1),
(981538, 115829, 28775, '<td valign="top">Like the concept in the title, but having a middle-class person walking around, through or out of the photo would have been a nice touch.</td>', 'Like the concept in the title, but having a middle-class person walking around, through or out of the photo would have been a nice touch.', '2004-10-31 15:55:16.000000', NULL, 1),
(981539, 115816, 28775, '<td valign="top">looks like tribal poverty. needs more light in foreground. too monotoned to get full impact and details.</td>', 'looks like tribal poverty. needs more light in foreground. too monotoned to get full impact and details.', '2004-10-31 15:56:03.000000', NULL, 1),
(981540, 115830, 28775, '<td valign="top">You captured it.</td>', 'You captured it.', '2004-10-31 15:56:45.000000', NULL, 1),
(981542, 115379, 28775, '<td valign="top">Would really liked to have seen his face.</td>', 'Would really liked to have seen his face.', '2004-10-31 15:57:09.000000', NULL, 1),
(981544, 115610, 28775, '<td valign="top">doesn''t really grab me and scream poverty</td>', 'doesn''t really grab me and scream poverty', '2004-10-31 15:58:04.000000', NULL, 1),
(981545, 115824, 28775, '<td valign="top">nice portrait.</td>', 'nice portrait.', '2004-10-31 15:58:23.000000', NULL, 1),
(981547, 114782, 28775, '<td valign="top">too cutesy. would say more right side up.</td>', 'too cutesy. would say more right side up.', '2004-10-31 15:58:53.000000', NULL, 1),
(981552, 115848, 28775, '<td valign="top">Smile in his eyes hasn''t convinced me he''s worried about a room. nice color though.</td>', 'Smile in his eyes hasn''t convinced me he''s worried about a room. nice color though.', '2004-10-31 16:03:37.000000', NULL, 1),
