(982836, 115841, 8759, '<td valign="top">Excellent colours and composition. Nice crisp image. Good capture of the bugs. Still does not tell me much. Good luck</td>', 'Excellent colours and composition. Nice crisp image. Good capture of the bugs. Still does not tell me much. Good luck', '2004-11-01 09:51:04.000000', NULL, 1),
(982882, 115826, 20662, '<td valign="top">Sharpening and leveling this would have helped a lot.</td>', 'Sharpening and leveling this would have helped a lot.', '2004-11-01 10:24:23.000000', NULL, 1),
(982896, 115796, 20662, '<td valign="top">Is there someone living under that overlook? Seeing him/her would have made this a believable photo. Right now it''s just a photo of the overlook.</td>', 'Is there someone living under that overlook? Seeing him/her would have made this a believable photo. Right now it''s just a photo of the overlook.', '2004-11-01 10:28:23.000000', NULL, 1),
