(985461, 114454, 8759, '<td valign="top">Looks like Romanian gypsies during autumn cabbage sells. Good luck</td>', 'Looks like Romanian gypsies during autumn cabbage sells. Good luck', '2004-11-02 07:57:54.000000', NULL, 1),
(985562, 115194, 18897, '<td valign="top">Well a bit of humour was needed in this challenge as well I guess, but as a Nikon owner I must say that you lack more than money.. :-)</td>', 'Well a bit of humour was needed in this challenge as well I guess, but as a Nikon owner I must say that you lack more than money.. :-)', '2004-11-02 09:20:19.000000', NULL, 1),
(985588, 115172, 18897, '<td valign="top">Very nice. The sepia tone, the contrast between rich and poor, right down to the facial expression. My top pick this round.</td>', 'Very nice. The sepia tone, the contrast between rich and poor, right down to the facial expression. My top pick this round.', '2004-11-02 09:52:44.000000', NULL, 1),
(985613, 115075, 26361, '<td valign="top">I like the title.  Also, I like not being able to see all of the guy.  Makes it feel like he has at least some of his privacy left.  Good exposure.</td>', 'I like the title.  Also, I like not being able to see all of the guy.  Makes it feel like he has at least some of his privacy left.  Good exposure.', '2004-11-02 10:08:08.000000', NULL, 1),
(985615, 115768, 26361, '<td valign="top">Great close-up and detail.  Good job on exposure.</td>', 'Great close-up and detail.  Good job on exposure.', '2004-11-02 10:09:27.000000', NULL, 1),
