(985830, 115151, 26361, '<td valign="top">Great concept &amp; focus.  Might be better if the top bill weren''t obviously for a business.</td>', 'Great concept & focus.  Might be better if the top bill weren''t obviously for a business.', '2004-11-02 11:33:28.000000', NULL, 1),
(985901, 115523, 26361, '<td valign="top">The reflections in the window are a bit distracting.  Interesting contrast between the office and the person.</td>', 'The reflections in the window are a bit distracting.  Interesting contrast between the office and the person.', '2004-11-02 12:02:10.000000', NULL, 1),
(985911, 115782, 26361, '<td valign="top">Good composition, though I''d prefer a tighter crop.  Makes me want to know the story behind the photo.</td>', 'Good composition, though I''d prefer a tighter crop.  Makes me want to know the story behind the photo.', '2004-11-02 12:06:11.000000', NULL, 1),
(985939, 115806, 26361, '<td valign="top">Would have liked this better if the person had been closer.  Maybe a tighter crop?</td>', 'Would have liked this better if the person had been closer.  Maybe a tighter crop?', '2004-11-02 12:16:15.000000', NULL, 1),
(985950, 115425, 26361, '<td valign="top">Interesting photo, but a bit dark.  Would love to know what the title means?</td>', 'Interesting photo, but a bit dark.  Would love to know what the title means?', '2004-11-02 12:20:51.000000', NULL, 1),
(985953, 115606, 26361, '<td valign="top">The background is very distracting.  Would love to see a tighter crop.</td>', 'The background is very distracting.  Would love to see a tighter crop.', '2004-11-02 12:22:35.000000', NULL, 1),
(985955, 115492, 26361, '<td valign="top">Interesting photo.  A better crop and focus on the flamigo would make it.</td>', 'Interesting photo.  A better crop and focus on the flamigo would make it.', '2004-11-02 12:23:24.000000', NULL, 1),
(985960, 115859, 26361, '<td valign="top">Ah, poor pig!  Great focus on the change.</td>', 'Ah, poor pig!  Great focus on the change.', '2004-11-02 12:24:25.000000', NULL, 1),
(985964, 114454, 25218, '<td valign="top">I like how the eye is lead through the photo, one person to the next</td>', 'I like how the eye is lead through the photo, one person to the next', '2004-11-02 12:26:23.000000', NULL, 1),
(985970, 114766, 25218, '<td valign="top">I really like this - great illustration of theme and very clear, nice tones of grey with bits of color. some may complain of the angle, but I think it adds a little something.</td>', 'I really like this - great illustration of theme and very clear, nice tones of grey with bits of color. some may complain of the angle, but I think it adds a little something.', '2004-11-02 12:29:07.000000', NULL, 1),
(985975, 114936, 25218, '<td valign="top">The detail in this is amazing. I''m not crazy about selective desaturation usually, but this is one of the few photos in the challenge that I keep coming back to.</td>', 'The detail in this is amazing. I''m not crazy about selective desaturation usually, but this is one of the few photos in the challenge that I keep coming back to.', '2004-11-02 12:30:32.000000', NULL, 1),
(985980, 115600, 25218, '<td valign="top">nice contrast of subject with advertisement. Quite moving</td>', 'nice contrast of subject with advertisement. Quite moving', '2004-11-02 12:31:13.000000', NULL, 1),
(985982, 115716, 25218, '<td valign="top">Nice colors</td>', 'Nice colors', '2004-11-02 12:32:09.000000', NULL, 1),
(985983, 114810, 25218, '<td valign="top">Unique idea and well shot</td>', 'Unique idea and well shot', '2004-11-02 12:32:41.000000', NULL, 1),
(985991, 115806, 25218, '<td valign="top">this is a great "found" photo opportunity, and I think if you could have zoomed in closer to the sign-holder, it would have been even better</td>', 'this is a great "found" photo opportunity, and I think if you could have zoomed in closer to the sign-holder, it would have been even better', '2004-11-02 12:35:14.000000', NULL, 1),
(985998, 114544, 25218, '<td valign="top">A friend of mine was watching while I was voting &amp; didn''t like your photo (sorry!), but I do - I like the framing hand in the foreground, that echoes the gentleman sitting in the background. I detect some distracting glare like you were behind glass, so I''m giving a 9.</td>', 'A friend of mine was watching while I was voting & didn''t like your photo (sorry!), but I do - I like the framing hand in the foreground, that echoes the gentleman sitting in the background. I detect some distracting glare like you were behind glass, so I''m giving a 9.', '2004-11-02 12:37:46.000000', NULL, 1),
(986004, 114834, 25218, '<td valign="top">this is excellent. One complaint: the colors look a little washed out from the light, which could be considered as a re-enforcement of the poverty theme, but is bothersome from an aesthetic point of view.</td>', 'this is excellent. One complaint: the colors look a little washed out from the light, which could be considered as a re-enforcement of the poverty theme, but is bothersome from an aesthetic point of view.', '2004-11-02 12:40:12.000000', NULL, 1),
(986007, 115793, 26361, '<td valign="top">Interesting trailer.  Would love to see it zoomed in tighter to show off the differing textures cause by aging and rust.</td>', 'Interesting trailer.  Would love to see it zoomed in tighter to show off the differing textures cause by aging and rust.', '2004-11-02 12:41:49.000000', NULL, 1),
(986008, 115401, 26361, '<td valign="top">The background needs blurred more, and a crop showing the rest of him would be better.</td>', 'The background needs blurred more, and a crop showing the rest of him would be better.', '2004-11-02 12:42:49.000000', NULL, 1),
(986010, 115598, 25218, '<td valign="top">Kind of funny, but doesn''t really make me think of poverty... tp isn''t that expensive.</td>', 'Kind of funny, but doesn''t really make me think of poverty... tp isn''t that expensive.', '2004-11-02 12:43:17.000000', NULL, 1),
