(1532829, 115077, 40376, '<td valign="top">Yes , the content matter is sad , but often so is life.<br/>A very emotional photo indeed but perfect for the task set.</td>', 'Yes , the content matter is sad , but often so is life.A very emotional photo indeed but perfect for the task set.', '2005-07-13 12:59:37.000000', NULL, 0),
(1571484, 115612, 27446, '<td valign="top">Thank you everyone for your comments. I try to think, and shoot things a little deeper than what''s on the surface. Poverty, to me anyway, can be understood also as a sense of wanting and needing what you can''t have. I submited this image because I feel this woman demonstrates those qualities. To me, she is reaching out in her poverty for a closer relationship with God. Thanks again for all your comments.</td>', 'Thank you everyone for your comments. I try to think, and shoot things a little deeper than what''s on the surface. Poverty, to me anyway, can be understood also as a sense of wanting and needing what you can''t have. I submited this image because I feel this woman demonstrates those qualities. To me, she is reaching out in her poverty for a closer relationship with God. Thanks again for all your comments.', '2005-07-29 07:28:38.000000', NULL, 0),
(1609462, 114861, 27812, '<td valign="top">love this pic, wonderful capture.</td>', 'love this pic, wonderful capture.', '2005-08-14 10:50:00.000000', NULL, 0),
